sys_variable_value.value:
(function execute(inputs, outputs) {

    var brl = parseFloat(inputs.amount_brl.replace(',', '.'));
    var rate = parseFloat(inputs.convertion_rate);
    var usd = brl*rate;
    outputs.amount_usd = usd;

})(inputs, outputs);

